    HWND     hwnd;                 // null => slot unused
    wchar_t  label[32];
    int      monitor;              // 1-based, matches "\\.\DISPLAYn" / Windows "Identify"
    DWORD    input;                // value written to VCP 0x60
    int      x, y;                 // screen position
    COLORREF color;
    int      opacity;              // whole-button opacity, MIN_OPACITY..100 (%)
    int      display;              // D_LABEL / D_ICON / D_BOTH
    int      lpos;                 // LP_TOP / LP_BOTTOM (only used with D_BOTH)
    wchar_t  icon[MAX_PATH];       // "" = none, "builtin:<id>" or the path of an .ico file
    int      iconOpacity;          // MIN_ICON_OPACITY..100 (%)
    int      iconSize;             // edge in px at 96 DPI
    int      noPad;                // 1 = no padding around the icon (icon-only: the bare icon, no background)
