// ----------------------------------------------------------------------------------------------
// Icons: built-in PNGs or any .ico file -> premultiplied 32-bit bitmap -> AlphaBlend with opacity
// Only native APIs: CreateIconFromResourceEx (handles PNG + BMP icon images), DrawIconEx, AlphaBlend.
// ----------------------------------------------------------------------------------------------
static uint32_t Rd32(const BYTE* p) {
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24);
}

static bool ReadFileAll(const wchar_t* path, BYTE** out, DWORD* size) {
    HANDLE f = CreateFileW(path, GENERIC_READ, FILE_SHARE_READ, nullptr, OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (f == INVALID_HANDLE_VALUE) return false;
    DWORD sz = GetFileSize(f, nullptr), rd = 0;
    if (sz == INVALID_FILE_SIZE || sz < 22 || sz > (8u << 20)) { CloseHandle(f); return false; }
    BYTE* buf = new (std::nothrow) BYTE[sz];
    if (!buf) { CloseHandle(f); return false; }
    BOOL ok = ReadFile(f, buf, sz, &rd, nullptr);
    CloseHandle(f);
    if (!ok || rd != sz) { delete[] buf; return false; }
    *out = buf; *size = sz;
    return true;
}

// Pick the image of an .ico that suits `target` px best (smallest one that is big enough, else the
// biggest) and turn it into an HICON at its native size - no scaling happens here.
static HICON IconFromIcoBytes(const BYTE* d, DWORD n, int target) {
    if (n < 22 || d[0] || d[1] || d[2] != 1 || d[3]) return nullptr;          // reserved = 0, type = 1 (icon)
    int count = d[4] | (d[5] << 8), best = -1, bestDim = 0;
    for (int i = 0; i < count && (DWORD)(6 + 16 * (i + 1)) <= n; i++) {
        const BYTE* e = d + 6 + 16 * i;
        int dim = e[0] ? e[0] : 256;
        DWORD bytes = Rd32(e + 8), off = Rd32(e + 12);
        if (!bytes || off > n || bytes > n - off) continue;
        bool better;
        if (best < 0)               better = true;
        else if (bestDim >= target) better = dim >= target && dim < bestDim;
        else                        better = dim > bestDim;
        if (better) { best = i; bestDim = dim; }
    }
    if (best < 0) return nullptr;
    const BYTE* e = d + 6 + 16 * best;
    return CreateIconFromResourceEx((PBYTE)d + Rd32(e + 12), Rd32(e + 8), TRUE, 0x00030000, bestDim, bestDim, LR_DEFAULTCOLOR);
}

// spec: "" (none) | "builtin:<id>" | path of an .ico file
static HICON LoadSpecIcon(const wchar_t* spec, int target) {
    if (!spec || !spec[0]) return nullptr;
    if (!wcsncmp(spec, L"builtin:", 8)) {
        for (int i = 0; i < NEMB; i++)
            if (!_wcsicmp(spec + 8, kEmb[i].id))
                return CreateIconFromResourceEx((PBYTE)kEmb[i].data, kEmb[i].size, TRUE, 0x00030000, 128, 128, LR_DEFAULTCOLOR);
        return nullptr;
    }
    BYTE* buf; DWORD n;
    if (!ReadFileAll(spec, &buf, &n)) return nullptr;
    HICON h = IconFromIcoBytes(buf, n, target);
    delete[] buf;
    return h;
}

static HBITMAP MakeDIB(int w, int h, void** bits) {
    BITMAPINFO bi = {};
    bi.bmiHeader.biSize = sizeof(BITMAPINFOHEADER);
    bi.bmiHeader.biWidth = w;
    bi.bmiHeader.biHeight = -h;                            // top-down
    bi.bmiHeader.biPlanes = 1;
    bi.bmiHeader.biBitCount = 32;
    bi.bmiHeader.biCompression = BI_RGB;
    return CreateDIBSection(nullptr, &bi, DIB_RGB_COLORS, bits, nullptr, 0);
}

static int IconNativeSize(HICON ic) {
    ICONINFO ii; int n = 0;
    if (GetIconInfo(ic, &ii)) {
        BITMAP bm;
        if (GetObject(ii.hbmColor ? ii.hbmColor : ii.hbmMask, sizeof(bm), &bm)) n = bm.bmWidth;
        if (ii.hbmColor) DeleteObject(ii.hbmColor);
        if (ii.hbmMask)  DeleteObject(ii.hbmMask);
    }
    return n;
}

// Draw the icon on black and on white; the difference gives alpha, the black render is the
// premultiplied colour. Works for any icon flavour (PNG, 32-bit alpha, old AND-mask icons).
static uint32_t* IconToPremul(HICON ic, int nat) {
    size_t cnt = (size_t)nat * nat;
    void *pb = nullptr, *pw = nullptr;
    HBITMAP bb = MakeDIB(nat, nat, &pb), bw = MakeDIB(nat, nat, &pw);
    uint32_t* out = nullptr;
    if (bb && bw) {
        HDC dc = CreateCompatibleDC(nullptr);
        if (dc) {
            memset(pb, 0x00, cnt * 4);
            memset(pw, 0xFF, cnt * 4);
            HGDIOBJ old = SelectObject(dc, bb);
            if (old) {
                DrawIconEx(dc, 0, 0, ic, nat, nat, 0, nullptr, DI_NORMAL);
                SelectObject(dc, bw);
                DrawIconEx(dc, 0, 0, ic, nat, nat, 0, nullptr, DI_NORMAL);
                GdiFlush();
                SelectObject(dc, old);
                out = new (std::nothrow) uint32_t[cnt];
                if (out) {
                    const BYTE* k = (const BYTE*)pb; const BYTE* w = (const BYTE*)pw;
                    for (size_t i = 0; i < cnt; i++, k += 4, w += 4) {
                        int d = ((int)w[0] - k[0] + (int)w[1] - k[1] + (int)w[2] - k[2]) / 3;
                        d = d < 0 ? 0 : d > 255 ? 255 : d;
                        int a = 255 - d;
                        int b = imin(k[0], a), g = imin(k[1], a), r = imin(k[2], a);
                        out[i] = ((uint32_t)a << 24) | ((uint32_t)r << 16) | ((uint32_t)g << 8) | (uint32_t)b;
                    }
                }
            }
            DeleteDC(dc);
        }
    }
    if (bb) DeleteObject(bb);
    if (bw) DeleteObject(bw);
    return out;
}

// High-quality resize of a square premultiplied image (area average down, bilinear up).
static void Resample(const uint32_t* s, int sw, uint32_t* d, int dw) {
    if (sw == dw) { memcpy(d, s, (size_t)sw * sw * 4); return; }
    float scale = (float)sw / dw;
    for (int y = 0; y < dw; y++) {
        for (int x = 0; x < dw; x++) {
            float c[4] = { 0, 0, 0, 0 };
            if (dw > sw) {                                  // bilinear
                float fx = (x + 0.5f) * scale - 0.5f, fy = (y + 0.5f) * scale - 0.5f;
                int ix = (int)floorf(fx), iy = (int)floorf(fy);
                float tx = fx - ix, ty = fy - iy;
                for (int j = 0; j < 2; j++)
                    for (int i = 0; i < 2; i++) {
                        int px = imax(0, imin(sw - 1, ix + i)), py = imax(0, imin(sw - 1, iy + j));
                        float wgt = (i ? tx : 1 - tx) * (j ? ty : 1 - ty);
                        uint32_t p = s[py * sw + px];
                        for (int k = 0; k < 4; k++) c[k] += ((p >> (8 * k)) & 255) * wgt;
                    }
            } else {                                        // box / area average
                float x0 = x * scale, x1 = (x + 1) * scale, y0 = y * scale, y1 = (y + 1) * scale, wt = 0;
                for (int iy = (int)y0; iy < (int)ceilf(y1) && iy < sw; iy++) {
                    float wy = fminf((float)iy + 1, y1) - fmaxf((float)iy, y0);
                    for (int ix = (int)x0; ix < (int)ceilf(x1) && ix < sw; ix++) {
                        float wx = fminf((float)ix + 1, x1) - fmaxf((float)ix, x0), wgt = wx * wy;
                        uint32_t p = s[iy * sw + ix];
                        for (int k = 0; k < 4; k++) c[k] += ((p >> (8 * k)) & 255) * wgt;
                        wt += wgt;
                    }
                }
                if (wt > 0) for (int k = 0; k < 4; k++) c[k] /= wt;
            }
            uint32_t o = 0;
            for (int k = 0; k < 4; k++) {
                int v = (int)(c[k] + 0.5f); v = v < 0 ? 0 : v > 255 ? 255 : v;
                o |= (uint32_t)v << (8 * k);
            }
            d[y * dw + x] = o;
        }
    }
}

static HBITMAP BuildIconBitmap(HICON ic, int px) {
    int nat = IconNativeSize(ic);
    if (nat < 8 || nat > 512) return nullptr;
    uint32_t* src = IconToPremul(ic, nat);
    if (!src) return nullptr;
    void* bits = nullptr;
    HBITMAP bm = MakeDIB(px, px, &bits);
    if (bm) Resample(src, nat, (uint32_t*)bits, px);
    delete[] src;
    return bm;
}

static HBITMAP LoadSpecBitmap(const wchar_t* spec, int px) {
    HICON ic = LoadSpecIcon(spec, px);
    if (!ic) return nullptr;
    HBITMAP bm = BuildIconBitmap(ic, px);
    DestroyIcon(ic);
    return bm;
}

static void DrawIconBmp(HDC dc, HBITMAP bm, int x, int y, int px, int opacityPct) {
    if (!bm) return;
    HDC s = CreateCompatibleDC(dc);
    if (!s) return;
    HGDIOBJ o = SelectObject(s, bm);
    if (!o) { DeleteDC(s); return; }
    BLENDFUNCTION bf = { AC_SRC_OVER, 0, (BYTE)(opacityPct * 255 / 100), AC_SRC_ALPHA };
    AlphaBlend(dc, x, y, px, px, s, 0, 0, px, px, bf);
    SelectObject(s, o);
    DeleteDC(s);
}

static void ReloadButtonIcon(Btn* b) {
    if (b->iconBmp) { DeleteObject(b->iconBmp); b->iconBmp = nullptr; }
    b->iconPx = 0;
    if (!b->icon[0]) return;
    int px = S(b->iconSize);
    HBITMAP bm = LoadSpecBitmap(b->icon, px);
    if (bm) { b->iconBmp = bm; b->iconPx = px; }
}

static void PlaceDefault(Btn* b, int index) {
    RECT wa; SystemParametersInfoW(SPI_GETWORKAREA, 0, &wa, 0);
    b->x = wa.right - S(120) - S(24);
    b->y = wa.top + S(24) + index * S(64);
}

